 for(const side of ['left','right']){const wrap=document.createElement('div');wrap.className='field';const lab=document.createElement('label');lab.className='fieldlabel';lab.textContent=side==='left'?'Left value':'Right value';const sel=document.createElement('select');sel.className='space';sel.setAttribute('aria-label',lab.textContent+' source');sel.add(new Option('Type a value',''));refs.forEach(r=>sel.add(new Option(r.group+' → '+r.label,r.value)));const text=document.createElement('input');text.setAttribute('aria-label',lab.textContent);text.className='space';text.oninput=()=>values[side]=text.value;sel.onchange=()=>{text.hidden=!!sel.value;values[side]=sel.value||text.value;};wrap.append(lab,sel,text);area.append(wrap);if(side==='left'){const op=document.createElement('select');op.id='conditionOperator';op.setAttribute('aria-label','Comparison');for(const [v,l] of [['equals','is equal to'],['contains','contains'],['greater','is greater than'],['less','is less than'],['greaterOrEquals','is at least'],['lessOrEquals','is at most']])op.add(new Option(l,v));area.append(op);}}
