function schemaDialog(field){modal('Generate a JSON schema','FROM A REPRESENTATIVE EXAMPLE','<p>Paste a small example of the data you expect. This generator uses the first array item and does not infer every possible variation or required field.</p><textarea id="schemaSample" rows="10" class="code" placeholder=\'{"name":"Example","items":[{"title":"Review"}]}\' aria-label="Sample JSON"></textarea><button id="generateSchema" class="primary space">Use generated schema</button>');$('generateSchema').onclick=()=>{try{const schema=C.schemaFrom(JSON.parse($('schemaSample').value));changeField(field,schema,true);closeModal();}catch(e){notify('That example is not valid JSON: '+e.message);}};}
function rawDialog(){const s=getSelected();if(!s)return;modal('Edit preserved JSON','ADVANCED · THIS ACTION ONLY','<p>Only this action is replaced. Names, metadata, retry settings, unknown properties, and nested actions are kept unless you remove them here. Use Undo to recover a prior version.</p><textarea id="rawEditor" rows="17" class="code" aria-label="Raw step JSON"></textarea><button id="applyRaw" class="primary space">Apply JSON</button>');$('rawEditor').value=C.j(s.a);$('applyRaw').onclick=()=>{try{const data=JSON.parse($('rawEditor').value);if(!C.object(data)||typeof data.type!=='string')throw Error('The action needs a type property.');mutate(()=>{if(s.trigger)project.definition.triggers[s.name]=data;else C.put(project.definition,s.path,data);C.register(project,data);for(const r of C.walk({actions:{Root:data}}))C.register(project,r.a);});closeModal();}catch(e){notify(e.message);}};}
function download(name,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
